CREATE TABLE app_users (id UUID PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(255) NOT NULL,phone VARCHAR(255),address VARCHAR(1000),enabled BOOLEAN NOT NULL);
CREATE TABLE students (id UUID PRIMARY KEY REFERENCES app_users(id),student_code VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE teachers (id UUID PRIMARY KEY REFERENCES app_users(id),department VARCHAR(255));
CREATE TABLE academic_terms (id UUID PRIMARY KEY,academic_year INTEGER NOT NULL,semester INTEGER NOT NULL CHECK(semester IN (1,2)),starts_on DATE NOT NULL,ends_on DATE NOT NULL,submission_deadline TIMESTAMPTZ NOT NULL,UNIQUE(academic_year,semester),CHECK(starts_on<=ends_on));
CREATE TABLE classrooms (id UUID PRIMARY KEY,academic_year INTEGER NOT NULL,grade_level INTEGER NOT NULL,room_label VARCHAR(255) NOT NULL,UNIQUE(academic_year,grade_level,room_label));
CREATE TABLE enrollments (id UUID PRIMARY KEY,student_id UUID NOT NULL REFERENCES students(id),classroom_id UUID NOT NULL REFERENCES classrooms(id),term_id UUID NOT NULL REFERENCES academic_terms(id),roll_number INTEGER NOT NULL,UNIQUE(student_id,term_id),UNIQUE(classroom_id,term_id,roll_number));
CREATE TABLE classroom_advisors (id UUID PRIMARY KEY,teacher_id UUID NOT NULL REFERENCES teachers(id),classroom_id UUID NOT NULL REFERENCES classrooms(id),term_id UUID NOT NULL REFERENCES academic_terms(id),UNIQUE(teacher_id,classroom_id,term_id));
CREATE TABLE activity_categories (id UUID PRIMARY KEY,code VARCHAR(255) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,description VARCHAR(255),color VARCHAR(255));
CREATE TABLE activity_requirements (id UUID PRIMARY KEY,term_id UUID NOT NULL REFERENCES academic_terms(id),category_id UUID NOT NULL REFERENCES activity_categories(id),grade_level INTEGER NOT NULL,metric VARCHAR(255) NOT NULL CHECK(metric IN ('COUNT','DURATION_MINUTES')),target_value INTEGER NOT NULL CHECK(target_value>0),UNIQUE(term_id,grade_level,category_id));
CREATE TABLE activities (id UUID PRIMARY KEY,student_id UUID NOT NULL REFERENCES students(id),term_id UUID NOT NULL REFERENCES academic_terms(id),category_id UUID NOT NULL REFERENCES activity_categories(id),reviewer_id UUID REFERENCES teachers(id),title VARCHAR(255),description VARCHAR(4000),activity_date DATE,start_time TIME,end_time TIME,duration_minutes INTEGER NOT NULL DEFAULT 0 CHECK(duration_minutes>=0),status VARCHAR(255) NOT NULL CHECK(status IN ('DRAFT','PENDING','APPROVED','REJECTED')),version BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,submitted_at TIMESTAMPTZ,CHECK(status='DRAFT' OR reviewer_id IS NOT NULL));
CREATE TABLE activity_status_history (id UUID PRIMARY KEY,activity_id UUID NOT NULL REFERENCES activities(id),actor_id UUID NOT NULL REFERENCES app_users(id),sequence INTEGER NOT NULL,from_status VARCHAR(255),to_status VARCHAR(255) NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,reason VARCHAR(1000),UNIQUE(activity_id,sequence));
CREATE TABLE favorite_teachers (id UUID PRIMARY KEY,student_id UUID NOT NULL REFERENCES students(id),teacher_id UUID NOT NULL REFERENCES teachers(id),UNIQUE(student_id,teacher_id));
CREATE INDEX idx_activity_student_term_status ON activities(student_id,term_id,status,created_at DESC);
CREATE INDEX idx_activity_reviewer_status ON activities(reviewer_id,status,submitted_at DESC);
CREATE INDEX idx_activity_category_date ON activities(student_id,term_id,category_id,activity_date);
CREATE INDEX idx_activity_history ON activity_status_history(activity_id,occurred_at,sequence);
CREATE INDEX idx_enrollment_classroom ON enrollments(classroom_id,term_id);
CREATE INDEX idx_advisor_teacher ON classroom_advisors(teacher_id,term_id);
CREATE TABLE SPRING_SESSION (PRIMARY_ID CHAR(36) NOT NULL,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME VARCHAR(100),CONSTRAINT SPRING_SESSION_PK PRIMARY KEY(PRIMARY_ID));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES (SESSION_PRIMARY_ID CHAR(36) NOT NULL,ATTRIBUTE_NAME VARCHAR(200) NOT NULL,ATTRIBUTE_BYTES BYTEA NOT NULL,CONSTRAINT SPRING_SESSION_ATTRIBUTES_PK PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME),CONSTRAINT SPRING_SESSION_ATTRIBUTES_FK FOREIGN KEY(SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE);
